from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class SibParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        cell_ent = self.enb_ent_config['cells'][self.cell_num]

        qrxlevminintraF = cell_ent.get('qrxlevminintra_f')
        if qrxlevminintraF:
            self.set_parameter('qrxlevminintraF', qrxlevminintraF)

        qrxlevmin = cell_ent.get('qrxlevmin')
        if qrxlevmin:
            self.set_parameter('qrxlevmin', qrxlevmin)

        pMaxOwnCell = cell_ent.get('p_max_own_cell')
        if pMaxOwnCell:
            self.set_parameter('pMaxOwnCell', pMaxOwnCell)
